import hashlib,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'evidence/nonmap_overlap_edges_work3.json').read_text(encoding='utf-8'))
prior=json.loads((ROOT/'evidence/boundary_revalidation_work3.json').read_text(encoding='utf-8'))['overlap']
actual=hashlib.sha256((ROOT/'evidence/genewars-1_1.exe').read_bytes()).hexdigest()
assert actual==data['target_sha256'] and len(data['seed_addresses'])==651
assert len(data['edges'])==data['edge_count']==969
assert len({e['candidate'] for e in data['edges']})==data['unique_nonseed_candidate_count']==865
assert len({(e['owner_seed'],e['candidate']) for e in data['edges']})==969
seedset=set(data['seed_addresses'])
assert all(e['owner_seed'] in seedset and e['owner_seed']!=e['candidate'] for e in data['edges'])
prior_seedpairs=len(prior['seed_to_seed_pairs']); prior_nonseed_edges=prior['current_seed_any_candidate_pairs']-prior_seedpairs
report=['# W3-010 — non-MAP CFG overlap ownership audit','',f"Target SHA-256: `{actual}`. MAIN.MAP SHA-256: `{data['map_sha256']}`.",'',f"The corrected-VA replay uses the {data['recovered_cfg_candidate_count']} recovered CFG entries plus all {data['map_public_candidate_count']} public MAIN.MAP entries in range; union candidate addresses: {data['candidate_universe_count']}. Only {data['map_function_like_seed_count']} function-like MAIN.MAP entries can own overlaps.",'',f"Current result: **{data['unique_nonseed_candidate_count']} unique nonseed candidates / {data['edge_count']} nonseed instruction-overlap edges / {data['seed_owners_involved']} seed owners**.",'',f"W3-004 recorded 857 unique nonseed partners and 1038 seed-any-candidate pairs; 77 are seed-to-seed, so prior nonseed edges sum to {prior_nonseed_edges}. Current totals differ by +{data['unique_nonseed_candidate_count']-857} candidates and +{data['edge_count']-prior_nonseed_edges} edges. Same PE and MAIN.MAP hashes. The old report kept per-seed totals but only up to three sample edges and no full candidate list. The current explicit universe includes all public MAP entries as candidate starts; those labels add reachable addresses beyond CFG function entries. Keep the exact 865/969 current table and prior 857/961 totals separately; an 8-address/8-edge historical delta remains for W3-011 to resolve.",'',"The older WORK1 audit (`map_overlap_ownership_work1.json`) reports 5735 candidates because its owner loop traverses all recovered CFGs rather than restricting owners to MAIN.MAP seeds; it includes candidate self-ownership. That count is invalid as a seed-owned overlap metric and is not a function count.",'','## Classification','',f"| Classification | Edges |\n|---|---:|",*([f"| `{k}` | {v} |" for k,v in data['classes'].items()]),'','Reachable instruction entries and shared tails remain boundary/ownership evidence. Thirteen addresses are `def_`/`jpt_` MAP flow labels. No candidate is promoted to a confirmed function. Every owner/candidate edge includes its exact VAs, MAP names, shared instruction count, and byte-decoded mnemonic samples in `evidence/nonmap_overlap_edges_work3.json`.','',"## Open delta",'',"W3-011 will find the 8 additional current candidates and determine which candidate inclusion rules created the historical shortfall. Until then, preserve the current exact table and the historical aggregate as separate results.",'','Reproduction: `py -3 tools/audit_nonmap_overlap_work3.py`; validation: `py -3 tests/test_nonmap_overlap_work3.py`.','']
(ROOT/'reports/coordination/nonmap_overlap_audit_work3.md').write_text('\n'.join(report),encoding='utf-8')
print(json.dumps({'candidate_universe':data['candidate_universe_count'],'unique_nonseed':data['unique_nonseed_candidate_count'],'edges':data['edge_count'],'owners':data['seed_owners_involved'],'classes':data['classes'],'prior_nonseed_edges':prior_nonseed_edges},indent=2))
